public static boolean order(BinNode<Range> t) {
    if (t == null) {
        return true;
    }
    Range r = t.getValue();
    if (t.hasLeft()) {
        Range left = t.getLeft().getValue();
        if (r.getLow() != left.getLow() || r.getHigh() < left.getHigh()) {
            return false;
        }
    }
    if (t.hasRight()) {
        Range right = t.getRight().getValue();
        if (r.getHigh() != right.getHigh() || r.getLow() > right.getLow()) {
            return false;
        }
    }
    if (t.hasLeft() && t.hasRight()) {
        if (t.getLeft().getValue().getHigh() >= t.getRight().getValue().getLow()) {
            return false;
        }
    }
    return order(t.getLeft()) && order(t.getRight());
}

